<?php
/** Pure tests for cross-request import staging and staged-plan commit. */
if ( ! class_exists( 'WP_Error' ) ) { class WP_Error { private $c,$m; function __construct($c='',$m=''){ $this->c=$c;$this->m=$m;} function get_error_code(){return $this->c;} function get_error_message(){return $this->m;} } }
function is_wp_error($v){return $v instanceof WP_Error;} function absint($v){return abs((int)$v);} function sanitize_key($k){return strtolower(preg_replace('/[^a-z0-9_\-]/','',(string)$k));} function is_email($e){return false!==filter_var($e,FILTER_VALIDATE_EMAIL);}
require_once __DIR__ . '/bootstrap-autoload.php';
use Certloom\Application\Contract\DomainImportStageInterface; use Certloom\Application\Contract\DomainImportTargetInterface; use Certloom\Application\Import\DomainImportStagingService; use Certloom\Application\Import\DomainImportStagedCommitService;

final class MemoryStage implements DomainImportStageInterface {
 public $rows=array(); public $existing=array();
 public function stage($job,$n,array $plan){$num=$plan['version']['display_number'];$hash=hash('sha256',json_encode($plan));$key=$job.':'.$n;if(isset($this->rows[$key])){if($this->rows[$key]['hash']===$hash)return array('outcome'=>'already_staged');return new WP_Error('changed','row changed');}foreach($this->rows as $r){if($r['job']===$job&&$r['num']===$num)return new WP_Error('duplicate','duplicate '.$num);} $out=isset($this->existing[$num])?'duplicate':'ready';$this->rows[$key]=array('job'=>$job,'row_number'=>$n,'num'=>$num,'hash'=>$hash,'plan'=>$plan,'outcome'=>$out,'commit_outcome'=>null,'target_series_id'=>null,'target_version_id'=>null);return array('outcome'=>$out);}
 public function read_batch($job,$after,$limit=500,$outcome='ready'){ $a=array();foreach($this->rows as $r){if($r['job']===$job&&$r['row_number']>$after&&$r['outcome']===$outcome&&empty($r['commit_outcome']))$a[]=$r;}usort($a,fn($x,$y)=>$x['row_number']<=>$y['row_number']);$a=array_slice($a,0,$limit);return array_map(fn($r)=>array('row_number'=>$r['row_number'],'display_number'=>$r['num'],'plan'=>$r['plan'],'outcome'=>$r['outcome'],'existing_series_id'=>null),$a);}
 public function summary($job){$s=array('total'=>0,'ready'=>0,'duplicate'=>0);foreach($this->rows as $r){if($r['job']!==$job)continue;$s['total']++;$s[$r['outcome']]++;}return $s;}
 public function mark_committed($job,$n,$outcome,$series_id=null,$version_id=null){$key=$job.':'.$n;if(!isset($this->rows[$key]))return new WP_Error('missing','missing');$this->rows[$key]['commit_outcome']=$outcome;$this->rows[$key]['target_series_id']=$series_id;$this->rows[$key]['target_version_id']=$version_id;return true;}
 public function commit_summary($job){$s=array('committed'=>0,'created'=>0,'corrected'=>0);foreach($this->rows as $r){if($r['job']!==$job||empty($r['commit_outcome']))continue;$s['committed']++;$s[$r['commit_outcome']]++;}return $s;}
 public function clear($job){foreach(array_keys($this->rows) as $k){if($this->rows[$k]['job']===$job)unset($this->rows[$k]);}return true;}
}
final class StagedTarget implements DomainImportTargetInterface { public $plans=array(); public function import($row,array $plan,$policy='skip'){ $this->plans[$row]=$plan; return array('outcome'=>'correct'===$policy?'corrected':'created'); } }
function st_same($e,$a,$m=''){if($e!==$a)throw new RuntimeException(($m?$m.': ':'').'Expected '.var_export($e,true).', got '.var_export($a,true));}
$job=str_repeat('d',32);$stage=new MemoryStage();$svc=new DomainImportStagingService($stage);
$r1=$svc->stage_batch(array(array('cert_number'=>'C-1','holder_name'=>'Alice'),array('cert_number'=>'C-2','holder_name'=>'Bob')),$job,0,false,'2026-08-22');st_same(2,$r1['ready'],'first batch ready');
$r2=$svc->stage_batch(array(array('cert_number'=>'C-3','holder_name'=>'Cara'),array('cert_number'=>'C-1','holder_name'=>'Duplicate')),$job,2,false,'2026-08-22');st_same(1,$r2['ready'],'second batch ready');st_same(1,$r2['errors'],'cross-batch duplicate blocked');echo "PASS  cross-request staging detects certificate-number duplicates across batches\n";
$r_retry=$svc->stage_batch(array(array('cert_number'=>'C-1','holder_name'=>'Alice'),array('cert_number'=>'C-2','holder_name'=>'Bob')),$job,0,false,'2026-08-22');st_same(2,$r_retry['already_staged'],'retry idempotent');st_same(0,$r_retry['errors'],'retry no errors');echo "PASS  retried preflight slice is idempotent for identical normalized plans\n";
$stage2=new MemoryStage();$stage2->existing['OLD-1']=99;$svc2=new DomainImportStagingService($stage2);$sum=$svc2->stage_batch(array(array('cert_number'=>'OLD-1','holder_name'=>'Existing')),$job,0,false,'2026-08-22');st_same(1,$sum['duplicates'],'existing live number classified duplicate');echo "PASS  preflight distinguishes existing live certificate-number assignments\n";
$target=new StagedTarget();$commit=new DomainImportStagedCommitService($stage,$target);$c=$commit->commit_batch($job,0,2,'skip');st_same(2,$c['created'],'first commit');st_same(false,$c['complete'],'more staged rows');$c2=$commit->commit_batch($job,$c['last_row'],2,'skip');st_same(1,$c2['created'],'second commit');st_same(true,$c2['complete'],'complete');st_same('Cara',$target->plans[3]['recipient']['display_name'],'commits staged plan');echo "PASS  commit consumes durable validated plans in bounded row order without reparsing source rows\n";
$target2=new StagedTarget();$commit2=new DomainImportStagedCommitService($stage2,$target2);$corrected=$commit2->commit_batch($job,0,10,'correct');st_same(1,$corrected['corrected'],'duplicate correction committed');st_same(true,$corrected['complete'],'duplicate correction complete');echo "PASS  correction policy consumes preflighted duplicate rows instead of silently skipping them\n";
echo "\n5 tests, 0 failures\n";
